  "title": "add-repr-to-method-not-allowed-error",
  "request": "Hey, can you add a __repr__ to MethodNotAllowedError so when I print it I see the status code and body? I'd like it to show something useful for debugging.",
  "edits": [
    {
      "path": "langfuse/api/commons/errors/method_not_allowed_error.py",
      "search": "    def __init__(
        self, body: typing.Any, headers: typing.Optional[typing.Dict[str, str]] = None
    ):
        super().__init__(status_code=405, headers=headers, body=body)",
      "replace": "    def __init__(
        self, body: typing.Any, headers: typing.Optional[typing.Dict[str, str]] = None
    ):
        super().__init__(status_code=405, headers=headers, body=body)

    def __repr__(self) -> str:
        return f"MethodNotAllowedError(status_code={self.status_code}, body={self.body!r})""
    }
  ],
  "test_path": "tests/unit/test_method_not_allowed_error.py",
  "test": "import pytest
from langfuse.api.commons.errors.method_not_allowed_error import MethodNotAllowedError

def test_method_not_allowed_error_repr():
    err = MethodNotAllowedError(body={"error": "not allowed"})
    rep = repr(err)
    assert "MethodNotAllowedError" in rep
    assert "status_code=405" in rep
    assert "'error': 'not allowed'" in rep
"
